    let fixtures: &[(&str, &str)] = &[
        (
            "No member. A marker is kept by room AND member — a person holding one room as two personas keeps one for each — so the key holder never infers whose marker is meant.",
            "{\n  \"readMarker\": {\n    \"version\": 415\n  },\n  \"roomId\": \"did:webvh:QmRoom:rooms.northwind.example:deal\"\n}",
        ),
        (
            "A member that is not a DID.",
            "{\n  \"member\": \"alice\",\n  \"readMarker\": {\n    \"version\": 415\n  },\n  \"roomId\": \"did:webvh:QmRoom:rooms.northwind.example:deal\"\n}",
        ),
        (
            "No marker. A set says where the member has read to; there is nothing else for it to say.",
            "{\n  \"member\": \"did:webvh:QmAlice:personas.example:northwind\",\n  \"roomId\": \"did:webvh:QmRoom:rooms.northwind.example:deal\"\n}",
        ),
        (
            "A marker with no version. The version is what a reader that keeps a copy of the room counts against, and what orders two markers.",
            "{\n  \"member\": \"did:webvh:QmAlice:personas.example:northwind\",\n  \"readMarker\": {\n    \"createdAt\": \"2027-02-01T10:14:02Z\"\n  },\n  \"roomId\": \"did:webvh:QmRoom:rooms.northwind.example:deal\"\n}",
        ),
        (
            "A negative version. `0` is the lowest: nothing in the room seen.",
            "{\n  \"member\": \"did:webvh:QmAlice:personas.example:northwind\",\n  \"readMarker\": {\n    \"version\": -1\n  },\n  \"roomId\": \"did:webvh:QmRoom:rooms.northwind.example:deal\"\n}",
        ),
        (
            "A version as a string. Markers are ordered by comparing versions as numbers; \"9\" would sort after \"415\".",
            "{\n  \"member\": \"did:webvh:QmAlice:personas.example:northwind\",\n  \"readMarker\": {\n    \"version\": \"415\"\n  },\n  \"roomId\": \"did:webvh:QmRoom:rooms.northwind.example:deal\"\n}",
        ),
        (
            "A createdAt that is not an RFC 3339 date-time. It is the host's timestamp, carried exactly as the host returned it.",
            "{\n  \"member\": \"did:webvh:QmAlice:personas.example:northwind\",\n  \"readMarker\": {\n    \"createdAt\": \"yesterday\",\n    \"version\": 415\n  },\n  \"roomId\": \"did:webvh:QmRoom:rooms.northwind.example:deal\"\n}",
        ),
        (
            "The message keys the member has read. A marker is a position, not a list of what was read: a list would grow with the room and would be a record of exactly which messages the member has seen.",
            "{\n  \"member\": \"did:webvh:QmAlice:personas.example:northwind\",\n  \"readMarker\": {\n    \"readKeys\": [\n      \"msg-0412\",\n      \"msg-0415\"\n    ],\n    \"version\": 415\n  },\n  \"roomId\": \"did:webvh:QmRoom:rooms.northwind.example:deal\"\n}",
        ),
        (
            "When the member read. A marker carries where they read to, never when; a reading time kept beside it would be the reading pattern the key holder is forbidden to keep.",
            "{\n  \"member\": \"did:webvh:QmAlice:personas.example:northwind\",\n  \"readMarker\": {\n    \"readAt\": \"2027-02-01T10:19:58Z\",\n    \"version\": 415\n  },\n  \"roomId\": \"did:webvh:QmRoom:rooms.northwind.example:deal\"\n}",
        ),
        (
            "rewind: false. Only `true` is meaningful; `false` would be a second spelling of the default.",
            "{\n  \"member\": \"did:webvh:QmAlice:personas.example:northwind\",\n  \"readMarker\": {\n    \"version\": 415\n  },\n  \"rewind\": false,\n  \"roomId\": \"did:webvh:QmRoom:rooms.northwind.example:deal\"\n}",
        ),
        (
            "A request to share the marker — a read receipt. There is no such member: a marker is never sent to the room, its host or another member, so no request carries a destination for it.",
            "{\n  \"member\": \"did:webvh:QmAlice:personas.example:northwind\",\n  \"readMarker\": {\n    \"version\": 415\n  },\n  \"roomId\": \"did:webvh:QmRoom:rooms.northwind.example:deal\",\n  \"shareWith\": \"did:webvh:QmBob:personas.example:northwind\"\n}",
        ),
        (
            "Bare/unnamespaced ext key — SPEC §4.5.1 requires every immediate child of ext to be reverse-DNS namespaced.",
            "{\n  \"ext\": {\n    \"bare-key\": {\n      \"anything\": \"here\"\n    }\n  },\n  \"member\": \"did:webvh:QmAlice:personas.example:northwind\",\n  \"readMarker\": {\n    \"version\": 415\n  },\n  \"roomId\": \"did:webvh:QmRoom:rooms.northwind.example:deal\"\n}",
        ),
    ];
